BEGIN;SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='2s';SELECT pg_advisory_xact_lock(2026083000261022);DO $release$ DECLARE n integer;BEGIN IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a JOIN population_top3000_202608_202609_v1.pipeline_control p USING(singleton) WHERE a.singleton AND a.owner_id='top3000-recovery-20261023-root-4b1314bcb5c2' AND a.owner_fence=2 AND a.stop_generation=0 AND a.owner_id=p.expected_owner_id AND a.owner_fence=p.expected_owner_fence AND a.stop_generation=p.expected_stop_generation AND a.enabled AND NOT a.stopped AND a.admitted_until>clock_timestamp() AND p.deadline>clock_timestamp() AND a.max_provider_requests-a.provider_requests>=40 AND a.max_http_invocations-a.http_invocations>=40) THEN RAISE EXCEPTION 'CURRENT_OWNER_OR_BUDGET_REQUIRED';END IF;UPDATE population_top3000_202608_202609_v1.pipeline_task SET not_before=clock_timestamp() WHERE family_id='D02' AND stage='ACQUIRE' AND payload->>'kind'='MASSIVE_GROUPED_DAILY_V2' AND status='READY' AND executions=0 AND checkpoint='{}' AND not_before='infinity';GET DIAGNOSTICS n=ROW_COUNT;IF n<>40 THEN RAISE EXCEPTION 'EXACT_FORTY_PARKED_NEW_SOURCE_TASKS_REQUIRED';END IF;INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('D02_DAILY_V2_REMAINING_DATES_RELEASED',jsonb_build_object('owner_fence',2,'dates',40,'new_provider_request_bound',40,'original_Aug3_source_preserved',true,'first_two_days_independent_typed_mismatches',0,'budget_cap_usd',250,'company_population_verified',false));PERFORM population_top3000_202608_202609_v1.pipeline_wake_v1('top3000-recovery-20261023-root-4b1314bcb5c2',2,'D02_REMAINING40_SOURCE_DATES_RELEASED_AFTER_MEASURED_FIRST_WAVE');END $release$;COMMIT;